    32→/**
    33→ * An {@link InputRow} iterator used by ingestion {@link Task}s. It can filter out rows which do not satisfy the given
    34→ * {@link #filter} or throw {@link ParseException} while parsing them. The relevant metric should be counted whenever
    35→ * it filters out rows based on the filter. ParseException handling is delegatged to {@link ParseExceptionHandler}.
    36→ */
    37→public class FilteringCloseableInputRowIterator implements CloseableIterator<InputRow>
    38→{
    39→  private final CloseableIterator<InputRow> delegate;
    40→  private final Predicate<InputRow> filter;
    41→  private final RowIngestionMeters rowIngestionMeters;
    42→  private final ParseExceptionHandler parseExceptionHandler;
    43→
    44→  private InputRow next;
    45→
    46→  public FilteringCloseableInputRowIterator(
    47→      CloseableIterator<InputRow> delegate,
    48→      Predicate<InputRow> filter,
    49→      RowIngestionMeters rowIngestionMeters,
    50→      ParseExceptionHandler parseExceptionHandler
    51→  )
    52→  {
    53→    this.delegate = delegate;
    54→    this.filter = filter;
    55→    this.rowIngestionMeters = rowIngestionMeters;
    56→    this.parseExceptionHandler = parseExceptionHandler;
    57→  }
    58→
    59→  @Override
    60→  public boolean hasNext()
    61→  {
    62→    while (next == null && delegate.hasNext()) {
    63→      try {
    64→        // delegate.next() can throw ParseException
    65→        final InputRow row = delegate.next();
    66→        // filter.test() can throw ParseException
    67→        if (filter.test(row)) {
    68→          next = row;
    69→        } else {
    70→          rowIngestionMeters.incrementThrownAway();
    71→        }
    72→      }
    73→      catch (ParseException e) {
    74→        parseExceptionHandler.handle(e);
    75→      }
    76→    }
    77→    return next != null;
    78→  }
    79→
    80→  @Override
    81→  public InputRow next()
    82→  {
    83→    if (!hasNext()) {
    84→      throw new NoSuchElementException();
    85→    }
    86→    final InputRow row = next;
    87→    next = null;
    88→    return row;
    89→  }
    90→
    91→  @Override
    92→  public void close() throws IOException
    93→  {
    94→    delegate.close();
    95→  }
    96→}
